// texts returns the messages without arguments in lang, nil for a
// language the catalog lacks.
func texts(lang string) *i18n.Texts {
	switch lang {
	case "en":
		return textsEn
	case "ja":
		return textsJa
	case "ko":
		return textsKo
	case "zh-Hans":
		return textsZhHans
	case "zh-Hant":
		return textsZhHant
	}
	return nil
}

// suppliedTexts are the messages without arguments other packages
// supply, by language and index.
var suppliedTexts = map[string]*[numTexts]string{}

// text says the message without arguments at i in the language of msgs,
// else of the languages it falls back to, else of the source.
func (msgs Messages) text(i int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, textsEn.At(i))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if t := suppliedTexts[lang]; t != nil && t[i] != "" {
			return t[i]
		}
		if lang == "" {
			return textsEn.At(i)
		}
		if t := texts(lang); t != nil {
			if s := t.At(i); s != "" {
				return s
			}
		}
	}
}

// Supply adds the messages t has in lang to the catalog, over its own.
// nsgo writes the calls, in the package that supplies them, which runs
// them as it initializes.
func Supply(lang string, t Translation) {
	if len(t.Texts) > 0 {
		st := suppliedTexts[lang]
		if st == nil {
			st = new([numTexts]string)
			suppliedTexts[lang] = st
		}
		for i, key := range keyOfText {
			if s, ok := t.Texts[key]; ok {
				st[i] = s
			}
		}
	}
	s := supplied[lang]
	if t.ComputersCertificate != nil {
		s.ComputersCertificate = t.ComputersCertificate
	}
	if t.ComputersFilmCount != nil {
		s.ComputersFilmCount = t.ComputersFilmCount
	}
	if t.ComputersOptions != nil {
		s.ComputersOptions = t.ComputersOptions
	}
	if t.ComputersUnpairTitle != nil {
		s.ComputersUnpairTitle = t.ComputersUnpairTitle
	}
	if t.ComputersUnpaired != nil {
		s.ComputersUnpaired = t.ComputersUnpaired
	}
	if t.ComputersUnreachable != nil {
		s.ComputersUnreachable = t.ComputersUnreachable
	}
	if t.DownloadsUsed != nil {
		s.DownloadsUsed = t.DownloadsUsed
	}
	if t.FilmDeleteTitle != nil {
		s.FilmDeleteTitle = t.FilmDeleteTitle
	}
	if t.FilmDownloading != nil {
		s.FilmDownloading = t.FilmDownloading
	}
	if t.FilmPaused != nil {
		s.FilmPaused = t.FilmPaused
	}
	if t.LibraryGone != nil {
		s.LibraryGone = t.LibraryGone
	}
	if t.OnboardingPaired != nil {
		s.OnboardingPaired = t.OnboardingPaired
	}
	if t.OnboardingStep != nil {
		s.OnboardingStep = t.OnboardingStep
	}
	if t.PairErrUnreachable != nil {
		s.PairErrUnreachable = t.PairErrUnreachable
	}
	if t.PlayerAsking != nil {
		s.PlayerAsking = t.PlayerAsking
	}
	if t.PlayerCardPlace != nil {
		s.PlayerCardPlace = t.PlayerCardPlace
	}
	if t.PlayerDelayPill != nil {
		s.PlayerDelayPill = t.PlayerDelayPill
	}
	if t.PlayerDelayReset != nil {
		s.PlayerDelayReset = t.PlayerDelayReset
	}
	if t.PlayerDelaySeconds != nil {
		s.PlayerDelaySeconds = t.PlayerDelaySeconds
	}
	if t.PlayerExplainBy != nil {
		s.PlayerExplainBy = t.PlayerExplainBy
	}
	if t.PlayerInfoLengthValue != nil {
		s.PlayerInfoLengthValue = t.PlayerInfoLengthValue
	}
	if t.PlayerNoteFor != nil {
		s.PlayerNoteFor = t.PlayerNoteFor
	}
	if t.PlayerPart != nil {
		s.PlayerPart = t.PlayerPart
	}
	if t.PlayerSleepMinutes != nil {
		s.PlayerSleepMinutes = t.PlayerSleepMinutes
	}
	if t.PlayerSleepPillIn != nil {
		s.PlayerSleepPillIn = t.PlayerSleepPillIn
	}
	if t.PlayerStudyFailed != nil {
		s.PlayerStudyFailed = t.PlayerStudyFailed
	}
	if t.PlayerStudyNoAI != nil {
		s.PlayerStudyNoAI = t.PlayerStudyNoAI
	}
	if t.PlayerStudyUnreachable != nil {
		s.PlayerStudyUnreachable = t.PlayerStudyUnreachable
	}
	if t.PlayerTabNotesCount != nil {
		s.PlayerTabNotesCount = t.PlayerTabNotesCount
	}
	supplied[lang] = s
	Catalog.Add(lang)
}

// arg is what an argument wrote, marked in the source's message for a
// pseudo locale.
func (msgs Messages) arg(s string) string {
	if msgs.mark {
		return i18n.Arg(s)
	}
	return s
}

